function a(e,t){return Math.floor(Math.random()*(t-e+1))+e}function p(e){return e[Math.floor(Math.random()*e.length)]}function o(e){return{type:"mcq",generate:e}}function h(e){return{type:"truefalse",generate:e}}function c(e){return{type:"fillblank",generate:e}}function d(e){return{type:"match",generate:e}}function r(e){return{type:"typeanswer",generate:e}}const g={M3:[o(()=>({cg:"CG1",q:"Which statement is true about a number line?",opts:["It only contains whole numbers","Every point on it corresponds to exactly one real number","It only goes in one direction","It starts at 1"],answer:1,explain:"A number line matches every point to exactly one real number, in order, extending infinitely both ways."})),h(()=>({cg:"CG2",q:"Zero on the number line is an optional marker — you could shift the whole line left or right and it would still work the same way.",answer:!1,explain:"Zero is the fixed reference point all distances and signs are measured from. Shifting it would change every number's meaning."})),c(()=>({cg:"CG3",q:"The sign in front of a number tells you which ___ from zero you're standing.",answer:"direction",accept:["direction","way","side"],explain:"Positive means right of zero, negative means left — the sign is directional, not about size."})),r(()=>{const e=a(-5,10),t=a(3,12),i=e+t;return{cg:"CG6",q:`What is the distance between ${e} and ${i} on the number line?`,answer:t,tolerance:0,explain:`Distance = |a − b| = |${e} − ${i}| = ${t}.`}}),d(()=>({cg:"CG14",q:"Match each sign combination to its quadrant.",pairs:[["(+, +)","Quadrant I"],["(−, +)","Quadrant II"],["(−, −)","Quadrant III"],["(+, −)","Quadrant IV"]],explain:"Quadrants go anticlockwise from top-right: I (+,+), II (−,+), III (−,−), IV (+,−)."})),o(()=>{const e=a(-6,6),t=e+1;return{cg:"CG4",q:`How many numbers exist strictly between ${e} and ${t} on the number line?`,opts:["0","Exactly 1","10","Infinitely many"],answer:3,explain:"However finely you slice the gap between any two numbers, there's always another number living there."}}),r(()=>{const e=a(-10,10),t=e+a(2,16),i=(e+t)/2;return{cg:"CG7",q:`What is the midpoint of ${e} and ${t}?`,answer:i,tolerance:.001,explain:`Midpoint = (${e} + ${t}) / 2 = ${i}.`}}),o(()=>({cg:"CG9",q:'Which axis is conventionally the horizontal, "input" axis?',opts:["The y-axis","The x-axis"],answer:1,explain:"x is horizontal and conventionally the input — you choose x first, then y comes out, as in y = f(x)."})),o(()=>({cg:"CG10",q:"What are the coordinates of the origin?",opts:["(1, 1)","(0, 0)","(x, y)","It has no fixed coordinates"],answer:1,explain:"The origin is where both axes' zeros line up — (0, 0)."})),c(()=>({cg:"CG11",q:"To plot the point (3, 4), you first move ___ units along the x-axis, then 4 units up.",answer:"3",accept:["3","three"],explain:"The first number in an ordered pair is always the horizontal move along x, done first."})),r(()=>{const t=p([[3,4,5],[6,8,10],[5,12,13],[8,15,17]]),i=a(-5,5),n=a(-5,5);return{cg:"CG15",q:`What is the distance between (${i},${n}) and (${i+t[0]},${n+t[1]})?`,answer:t[2],tolerance:.001,explain:`distance² = ${t[0]}² + ${t[1]}² = ${t[0]*t[0]} + ${t[1]*t[1]} = ${t[2]*t[2]}, so distance = ${t[2]}.`}}),o(()=>({cg:"CG18",q:"A line passes through Quadrant I, cuts into II, and reaches III — never touching IV. Its steepness is:",opts:["Positive","Negative","Zero","Undefined"],answer:0,explain:"To sweep through I, II, and III without ever touching IV, x and y must increase together — that's positive steepness."})),r(()=>{const e=a(0,5),t=a(0,5),i=e+a(1,6),n=t+a(1,8);return{cg:"CG19",q:`Between points (${e}, ${t}) and (${i}, ${n}), what is Δy (the vertical change)?`,answer:n-t,tolerance:0,explain:`Δy = y₂ − y₁ = ${n} − ${t} = ${n-t}.`}}),r(()=>{const e=a(1,5);let t=a(-4,4);t===0&&(t=2);const i=t*e,n=a(-5,5),s=a(-5,5),l=n+e,u=s+i;return{cg:"CG20",q:`Using points (${n}, ${s}) and (${l}, ${u}), what is the gradient (slope)?`,answer:t,tolerance:.001,explain:`m = Δy/Δx = (${u}−${s}) / (${l}−${n}) = ${i} / ${e} = ${t}.`}}),h(()=>({cg:"CG22",q:"A perfectly horizontal line has an undefined gradient.",answer:!1,explain:"A horizontal line has Δy = 0, so its gradient is 0 — not undefined. A vertical line has undefined gradient because Δx = 0."})),c(()=>({cg:"CG24",q:"In the equation y = mx + c, the letter ___ controls the lean (steepness) of the line.",answer:"m",accept:["m","M"],explain:"m is the gradient (slope) — it controls how steep the line is. c controls where it crosses the y-axis."}))],P1:[o(()=>({cg:"P1-1",q:"According to Newton's first law, what happens to a moving object if no force acts on it?",opts:["It gradually slows down and stops","It keeps moving in a straight line at constant speed","It speeds up","It falls to the ground"],answer:1,explain:"Newton's first law says a moving object keeps moving in a straight line at constant speed unless a force acts on it."})),h(()=>({cg:"P1-2",q:"Friction only occurs between rough surfaces — smooth surfaces have no friction at all.",answer:!1,explain:"Even very smooth surfaces have some friction. The smoother the surfaces, the less friction — but it never disappears completely."})),r(()=>{const e=a(10,50),t=a(2,10);return{cg:"P1-3",q:`A force of ${e}N is applied to a ${t}kg object. What is its acceleration? (F = ma)`,answer:e/t,tolerance:.01,explain:`a = F/m = ${e}/${t} = ${(e/t).toFixed(2)} m/s².`}}),c(()=>({cg:"P1-4",q:"The force that opposes motion between two surfaces in contact is called ___.",answer:"friction",accept:["friction","Friction"],explain:"Friction is the force that resists motion when two surfaces slide against each other."}))],C1:[o(()=>({cg:"C1-1",q:"How many naturally occurring elements are there?",opts:["37","92","118","Over 200"],answer:2,explain:"There are 118 known elements. 92 occur naturally on Earth; the rest are man-made in laboratories."})),h(()=>({cg:"C1-2",q:'The word "atom" comes from the Greek word "atomos", meaning "uncuttable".',answer:!0,explain:`Greek philosophers coined "atomos" to describe the smallest possible piece of matter — something that can't be divided further.`})),c(()=>({cg:"C1-3",q:"The atomic number (Z) equals the number of ___ in the nucleus.",answer:"protons",accept:["protons","proton"],explain:"The atomic number is the count of protons in the nucleus — change it and you change the element itself."})),d(()=>({cg:"C1-4",q:"Match each subatomic particle to its charge.",pairs:[["Proton","Positive (+)"],["Neutron","No charge (0)"],["Electron","Negative (−)"]],explain:"Protons are positive, electrons are negative, and neutrons have no charge."}))],P2:[o(()=>({cg:"P2-1",q:"What is the formal definition of energy?",opts:["The speed of an object","The capacity to do work","The mass of an object","The temperature of a substance"],answer:1,explain:"Energy is formally defined as the capacity to do work — a force moving something over a distance."})),h(()=>({cg:"P2-2",q:"Energy can be created from nothing as long as it is used immediately.",answer:!1,explain:"Energy cannot be created or destroyed. The total amount of energy in a closed system always stays the same."})),c(()=>({cg:"P2-3",q:"Energy is measured in ___.",answer:"joules",accept:["joules","Joules","joule","J"],explain:"The joule (J) is the standard unit of energy."})),o(()=>({cg:"P2-4",q:"A boulder at the top of a hill has what kind of energy?",opts:["Kinetic energy","Potential energy","Thermal energy","Electrical energy"],answer:1,explain:"A boulder at the top of a hill has gravitational potential energy — stored energy, waiting to be released."})),r(()=>({cg:"P2-5",q:"If a 2kg object is lifted 5 metres, how much gravitational potential energy does it gain? (g = 10 m/s², E = mgh)",answer:100,tolerance:.5,explain:"E = m × g × h = 2 × 10 × 5 = 100 joules."}))],P3:[o(()=>({cg:"P3-1",q:"Which statement about gravity is true?",opts:["Gravity only exists between large objects like planets","Every two objects in the universe pull on each other","Gravity can both attract and repel","Gravity is a type of magnetism"],answer:1,explain:"Every two objects in the universe pull on each other through gravity — you, your phone, the Earth, everything."})),h(()=>({cg:"P3-2",q:"The Moon is constantly falling toward the Earth, but keeps missing it.",answer:!0,explain:`The Moon is indeed falling toward Earth due to gravity, but its sideways speed means it keeps "missing" — that's what an orbit is.`})),c(()=>({cg:"P3-3",q:"The force of gravity between two objects depends on their ___ and the distance between them.",answer:"mass",accept:["mass","masses","Mass"],explain:"Gravity depends on the masses of the two objects (more mass = stronger pull) and the distance between them (farther apart = weaker pull)."})),r(()=>{const e=p([2,3,4]);return{cg:"P3-4",q:`If you double the distance between two objects, gravity drops to 1/4. If you triple it, gravity drops to 1/9. If you make it ${e} times farther, what fraction is gravity?`,answer:1/(e*e),tolerance:.001,explain:`Gravity follows an inverse square law: ${e}× farther = 1/${e*e} the strength.`}})],M1:[o(()=>({cg:"M1-1",q:"What is a limit?",opts:["A barrier that cannot be crossed","A value that a number creeps closer to but never quite reaches","The exact answer to any maths problem","A type of equation"],answer:1,explain:"A limit is a value that a number or sequence creeps closer and closer to, without necessarily ever landing on it exactly."})),o(()=>({cg:"M1-2",q:"What is 1 ÷ 0?",opts:["Infinity","Zero","One","Undefined"],answer:3,explain:"1 ÷ 0 is undefined, not infinity. Maths simply breaks — you can never divide by zero."})),h(()=>({cg:"M1-3",q:"The area of a circle can be found by filling it with polygons with more and more sides, and observing where the area heads.",answer:!0,explain:"This is the classic limit approach: draw a polygon inside the circle, increase its sides toward infinity, and the polygon's area approaches the circle's true area."})),c(()=>({cg:"M1-4",q:"Newton and ___ independently developed calculus at around the same time.",answer:"Leibniz",accept:["Leibniz","leibniz","Gottfried Leibniz","G. Leibniz"],explain:"Isaac Newton and Gottfried Leibniz independently invented calculus in the late 1600s."})),o(()=>({cg:"M1-5",q:"A function is best described as:",opts:["A difficult equation to solve","A machine that maps each input to exactly one output","A type of graph","A number that never changes"],answer:1,explain:"A function is a machine: feed it an input (x), and it reliably produces one output (f(x)). Like a vending machine."})),r(()=>({cg:"M1-6",q:"If f(x) = 2x + 3, what is f(5)?",answer:13,tolerance:0,explain:"f(5) = 2(5) + 3 = 10 + 3 = 13."}))]};function m(e,t=10){const i=g[e];if(!i)return[];const n=i.map(s=>{const l=s.generate();return{type:s.type,...l}});for(let s=n.length-1;s>0;s--){const l=Math.floor(Math.random()*(s+1));[n[s],n[l]]=[n[l],n[s]]}return n.slice(0,Math.min(t,n.length))}export{m as g};
